+import { rename, writeFile } from "node:fs/promises";
+import { join } from "node:path";
+
+type Status = "open" | "done";
+type Task = {
+  id: number;
+  title: string;
+  status: Status;
+  createdAt: string;
+  tags: string[];
+  due?: string;
+  completedAt?: string;
+};
+type Database = { tasks: Task[]; nextId: number };
+
+const file = process.env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");
+const fail = (message: string): never => {
+  console.error(message);
+  process.exit(1);
+};
+
+function usage(): never { fail("Usage: add, list, done, delete, or stats"); }
+
+function parseDate(value: string): string {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) fail(`Invalid date: ${value}`);
+  const [y, m, d] = value.split("-").map(Number);
+  const date = new Date(Date.UTC(y, m - 1, d));
+  if (date.getUTCFullYear() !== y || date.getUTCMonth() !== m - 1 || date.getUTCDate() !== d) fail(`Invalid date: ${value}`);
+  return value;
+}
+
+function readOption(args: string[], name: string): string | undefined {
+  const index = args.indexOf(name);
+  if (index < 0) return undefined;
+  if (index + 1 >= args.length || args[index + 1].startsWith("--")) fail(`Missing value for ${name}`);
+  return args[index + 1];
+}
+
+function ensureFlags(args: string[], allowed: string[]) {
+  for (let i = 0; i < args.length; i++) {
+    if (!args[i].startsWith("--")) continue;
+    if (!allowed.includes(args[i])) fail(`Unknown flag: ${args[i]}`);
+    if (i + 1 >= args.length || args[i + 1].startsWith("--")) fail(`Missing value for ${args[i]}`);
+    i++;
+  }
+}
+
+async function load(): Promise<Database> {
+  const source = Bun.file(file);
+  if (!(await source.exists())) return { tasks: [], nextId: 1 };
+  let value: unknown;
+  try { value = JSON.parse(await source.text()); } catch { fail("Malformed database"); }
+  if (!value || typeof value !== "object" || !Array.isArray((value as Database).tasks) || !Number.isInteger((value as Database).nextId)) fail("Malformed database");
+  const db = value as Database;
+  if (db.nextId < 1 || db.tasks.some((t) => !t || typeof t !== "object" || !Number.isInteger(t.id) || typeof t.title !== "string" || !["open", "done"].includes(t.status))) fail("Malformed database");
+  return db;
+}
+
+async function save(db: Database) {
+  const temporary = `${file}.tmp-${process.pid}-${Date.now()}`;
+  try { await writeFile(temporary, JSON.stringify(db, null, 2) + "\n", "utf8"); await rename(temporary, file); }
+  catch { fail("Unable to save database"); }
+}
+
+function idOf(value: string | undefined): number {
+  if (!value || !/^\d+$/.test(value) || Number(value) < 1) fail("Invalid task ID");
+  return Number(value);
+}
+
+async function main() {
+  const [command, ...args] = Bun.argv.slice(2);
+  if (!command) usage();
+  const db = await load();
+  let result: unknown;
+  if (command === "add") {
+    ensureFlags(args, ["--title", "--tags", "--due"]);
+    const title = readOption(args, "--title");
+    if (!title?.trim()) fail("Title must not be empty");
+    const dueValue = readOption(args, "--due");
+    const tags = [...new Set((readOption(args, "--tags") || "").split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
+    const task: Task = { id: db.nextId++, title, status: "open", createdAt: new Date().toISOString(), tags };
+    if (dueValue !== undefined) task.due = parseDate(dueValue);
+    db.tasks.push(task); await save(db); result = task;
+  } else if (command === "list") {
+    ensureFlags(args, ["--status", "--tag", "--overdue"]);
