+    if (overdue !== undefined) parseDate(overdue);
+    result = db.tasks.filter((task) => (status === undefined || task.status === status) && (tag === undefined || task.tags.includes(tag)) && (overdue === undefined || (task.status === "open" && !!task.due && task.due < overdue))).sort((a, b) => a.id - b.id);
+  } else if (command === "done") {
+    if (args.length !== 1) fail("Usage: done ID");
+    const task = db.tasks.find((item) => item.id === idOf(args[0]));
