+import { existsSync, readFileSync, renameSync, writeFileSync } from "node:fs";
+import { dirname, join } from "node:path";
+
+type Status = "open" | "done";
+type Task = { id: number; title: string; status: Status; createdAt: string; tags: string[]; due?: string; completedAt?: string };
+type Database = { tasks: Task[] };
+
+const file = process.env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");
+const json = (value: unknown) => console.log(JSON.stringify(value));
+const fail = (message: string): never => { throw new Error(message); };
+
+function validDate(value: string): boolean {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
+  const [y, m, d] = value.split("-").map(Number);
+  const date = new Date(Date.UTC(y, m - 1, d));
+  return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
+}
+function load(): Database {
+  if (!existsSync(file)) return { tasks: [] };
+  let parsed: unknown;
+  try { parsed = JSON.parse(readFileSync(file, "utf8")); } catch { fail("malformed database"); }
+  if (!parsed || typeof parsed !== "object" || !Array.isArray((parsed as any).tasks)) fail("malformed database");
+  const tasks = (parsed as any).tasks as Task[];
+  if (tasks.some(t => !t || !Number.isInteger(t.id) || t.id < 1 || typeof t.title !== "string" || !["open", "done"].includes(t.status) || !Array.isArray(t.tags))) fail("malformed database");
+  return { tasks };
+}
+function save(db: Database) {
+  const temporary = `${file}.tmp-${process.pid}-${Date.now()}`;
+  try { writeFileSync(temporary, JSON.stringify(db, null, 2) + "\n", { encoding: "utf8", flag: "wx" }); renameSync(temporary, file); }
+  catch (e) { try { if (existsSync(temporary)) Bun.file(temporary).delete(); } catch {} throw e; }
+}
+function options(args: string[], allowed: string[]): Map<string, string> {
+  const out = new Map<string, string>();
+  for (let i = 0; i < args.length; i++) {
+    const key = args[i];
+    if (!key.startsWith("--") || !allowed.includes(key)) fail(`unknown flag: ${key}`);
+    if (out.has(key)) fail(`duplicate flag: ${key}`);
+    const value = args[++i];
+    if (value === undefined || value.startsWith("--")) fail(`missing value for ${key}`);
+    out.set(key, value);
+  }
+  return out;
+}
+function idOf(value: string): number { if (!/^\d+$/.test(value) || Number(value) < 1) fail("invalid task id"); return Number(value); }
+function today(): string { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`; }
+
+function run(args: string[]): unknown {
+  const command = args.shift();
+  if (!command) fail("missing command");
+  const db = load();
+  if (command === "add") {
+    const o = options(args, ["--title", "--tags", "--due"]);
+    const title = o.get("--title")?.trim();
+    if (!title) fail("title is required and cannot be empty");
+    const due = o.get("--due");
+    if (due && !validDate(due)) fail("invalid due date");
+    const tags = [...new Set((o.get("--tags") || "").split(",").map(x => x.trim().toLowerCase()).filter(Boolean))];
+    const task: Task = { id: db.tasks.reduce((n, t) => Math.max(n, t.id), 0) + 1, title, status: "open", createdAt: new Date().toISOString(), tags };
+    if (due) task.due = due;
+    db.tasks.push(task); save(db); return task;
+  }
+  if (command === "list") {
+    const o = options(args, ["--status", "--tag", "--overdue"]);
+    const status = o.get("--status"); if (status && status !== "open" && status !== "done") fail("invalid status");
+    const overdue = o.get("--overdue"); if (overdue && !validDate(overdue)) fail("invalid overdue date");
+    const tag = o.get("--tag")?.trim().toLowerCase();
+    return db.tasks.filter(t => (!status || t.status === status) && (!tag || t.tags.includes(tag)) && (!overdue || (t.status === "open" && !!t.due && t.due < overdue))).sort((a,b) => a.id-b.id);
+  }
+  if (command === "done" || command === "delete") {
+    if (args.length !== 1 || args[0].startsWith("--")) fail(`${command} requires an ID`);
+    const id = idOf(args[0]); const task = db.tasks.find(t => t.id === id); if (!task) fail("task not found");
+    if (command === "delete") { db.tasks = db.tasks.filter(t => t.id !== id); save(db); return task; }
+    if (task.status === "open") { task.status = "done"; task.completedAt = new Date().toISOString(); save(db); }
+    return task;
+  }
