+import { rename } from "node:fs/promises";
+import { join } from "node:path";
+
+type Status = "open" | "done";
+type Task = {
+  id: number;
+  title: string;
+  status: Status;
+  createdAt: string;
+  tags: string[];
+  due?: string;
+  completedAt?: string;
+};
+type Database = { nextId: number; tasks: Task[] };
+
+const file = process.env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");
+
+function fail(message: string): never {
+  console.error(message);
+  console.log(JSON.stringify({ error: message }));
+  process.exit(1);
+}
+
+function dateOnly(value: string): string {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) fail(`Invalid date: ${value}`);
+  const [year, month, day] = value.split("-").map(Number);
+  const date = new Date(Date.UTC(year, month - 1, day));
+  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) {
+    fail(`Invalid date: ${value}`);
+  }
+  return value;
+}
+
+function parseId(value: string): number {
+  if (!/^\d+$/.test(value) || Number(value) < 1 || !Number.isSafeInteger(Number(value))) fail(`Invalid task ID: ${value}`);
+  return Number(value);
+}
+
+function options(args: string[], allowed: Set<string>): Map<string, string> {
+  const result = new Map<string, string>();
+  for (let i = 0; i < args.length; i++) {
+    const flag = args[i];
+    if (!flag.startsWith("--") || !allowed.has(flag)) fail(`Unknown flag: ${flag}`);
+    if (result.has(flag)) fail(`Duplicate flag: ${flag}`);
+    const value = args[++i];
+    if (value === undefined || value.startsWith("--")) fail(`Missing value for ${flag}`);
+    result.set(flag, value);
+  }
+  return result;
+}
+
+async function load(): Promise<Database> {
+  const exists = await Bun.file(file).exists();
+  if (!exists) return { nextId: 1, tasks: [] };
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(await Bun.file(file).text());
+  } catch {
+    fail("Malformed database");
+  }
+  if (!parsed || typeof parsed !== "object" || !Array.isArray((parsed as any).tasks) ||
+      !Number.isSafeInteger((parsed as any).nextId) || (parsed as any).nextId < 1) fail("Malformed database");
+  const db = parsed as Database;
+  const ids = new Set<number>();
+  for (const task of db.tasks) {
+    if (!task || typeof task !== "object" || !Number.isSafeInteger(task.id) || task.id < 1 || ids.has(task.id) ||
+        typeof task.title !== "string" || !["open", "done"].includes(task.status) || typeof task.createdAt !== "string" ||
+        !Array.isArray(task.tags) || task.tags.some((tag) => typeof tag !== "string")) fail("Malformed database");
+    ids.add(task.id);
+  }
+  return db;
+}
+
+async function save(db: Database): Promise<void> {
+  const temporary = `${file}.tmp-${process.pid}-${Math.random().toString(36).slice(2)}`;
+  try {
+    await Bun.write(temporary, `${JSON.stringify(db, null, 2)}\n`);
+    await rename(temporary, file);
+  } catch (error) {
+    try { await Bun.file(temporary).delete(); } catch {}
+    fail(`Could not save database: ${error instanceof Error ? error.message : String(error)}`);
+  }
+}
+
+function today(): string {
+  const now = new Date();
+  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
+}
+
+async function main(): Promise<void> {
+  const [command, ...args] = Bun.argv.slice(2);
+  if (!command) fail("Missing command");
+  const db = await load();
+  let output: unknown;
+
+  if (command === "add") {
+    const opts = options(args, new Set(["--title", "--tags", "--due"]));
+    const title = opts.get("--title")?.trim();
+    if (!title) fail("Title is required and cannot be empty");
+    const tags = [...new Set((opts.get("--tags") || "").split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
+    const task: Task = { id: db.nextId++, title, status: "open", createdAt: new Date().toISOString(), tags };
+    const due = opts.get("--due");
+    if (due !== undefined) task.due = dateOnly(due);
+    db.tasks.push(task);
+    await save(db);
+    output = task;
+  } else if (command === "list") {
+    const opts = options(args, new Set(["--status", "--tag", "--overdue"]));
+    const status = opts.get("--status");
+    if (status && status !== "open" && status !== "done") fail(`Invalid status: ${status}`);
+    const tag = opts.get("--tag")?.trim().toLowerCase();
+    const overdue = opts.get("--overdue");
+    if (overdue) dateOnly(overdue);
+    output = db.tasks.filter((task) => (!status || task.status === status) &&
+      (!tag || task.tags.includes(tag)) && (!overdue || (task.status === "open" && !!task.due && task.due < overdue)))
+      .sort((a, b) => a.id - b.id);
+  } else if (command === "done") {
+    if (args.length !== 1 || args[0].startsWith("--")) fail("Usage: done ID");
+    const id = parseId(args[0]);
+    const task = db.tasks.find((item) => item.id === id);
+    if (!task) fail(`Task not found: ${id}`);
+    if (task.status === "open") { task.status = "done"; task.completedAt = new Date().toISOString(); await save(db); }
+    output = task;
+  } else if (command === "delete") {
+    if (args.length !== 1 || args[0].startsWith("--")) fail("Usage: delete ID");
+    const id = parseId(args[0]);
+    const index = db.tasks.findIndex((item) => item.id === id);
+    if (index < 0) fail(`Task not found: ${id}`);
+    db.tasks.splice(index, 1);
+    await save(db);
+    output = { deleted: id };
+  } else if (command === "stats") {
+    if (args.length) fail(`Unknown flag: ${args[0]}`);
+    const open = db.tasks.filter((task) => task.status === "open");
+    output = { total: db.tasks.length, open: open.length, done: db.tasks.length - open.length,
+      overdue: open.filter((task) => !!task.due && task.due < today()).length };
+  } else fail(`Unknown command: ${command}`);
+  console.log(JSON.stringify(output));
+}
+
+main().catch((error) => fail(error instanceof Error ? error.message : String(error)));
