+  }
+  if (!value || typeof value !== "object") fail("Malformed database");
+  const store = value as Partial<Store>;
+  if (!Array.isArray(store.tasks) || !Number.isInteger(store.nextId) || store.nextId < 1) {
+    fail("Malformed database");
+  }
+  const ids = new Set<number>();
+  for (const task of store.tasks) {
+    if (!task || typeof task !== "object") fail("Malformed database");
+    const item = task as Partial<Task>;
+    if (!Number.isInteger(item.id) || item.id < 1 || ids.has(item.id) || typeof item.title !== "string" ||
+      (item.status !== "open" && item.status !== "done") || typeof item.createdAt !== "string" ||
+      !Array.isArray(item.tags) || item.tags.some((tag) => typeof tag !== "string") ||
+      (item.due !== undefined && (typeof item.due !== "string" || !validDate(item.due))) ||
+      (item.completedAt !== undefined && typeof item.completedAt !== "string")) {
+      fail("Malformed database");
+    }
+    ids.add(item.id);
+  }
+  if (store.tasks.some((task) => task.id >= store.nextId)) fail("Malformed database");
+  return store as Store;
+}
+
+function writeStore(store: Store): void {
+  const temporaryPath = `${databasePath}.tmp-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
+  try {
